DROP TABLE IF EXISTS `received_emails`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `received_emails` (
  `id` int NOT NULL AUTO_INCREMENT,
  `prospect_id` int DEFAULT NULL,
  `agent_id` int NOT NULL,
  `from_email` varchar(255) NOT NULL,
  `subject` varchar(500) DEFAULT NULL,
  `body` text,
  `body_text` text,
  `received_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `sentiment` enum('positive','neutral','negative') DEFAULT 'neutral',
  `actioned` tinyint(1) DEFAULT '0',
  `action_type` varchar(50) DEFAULT NULL,
  `actioned_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `prospect_id` (`prospect_id`),
  KEY `idx_agent_received` (`agent_id`,`received_at`),
  KEY `idx_actioned` (`actioned`),
  CONSTRAINT `received_emails_ibfk_1` FOREIGN KEY (`prospect_id`) REFERENCES `prospects` (`id`) ON DELETE SET NULL,
  CONSTRAINT `received_emails_ibfk_2` FOREIGN KEY (`agent_id`) REFERENCES `agents` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

