DROP TABLE IF EXISTS `sent_emails`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sent_emails` (
  `id` int NOT NULL AUTO_INCREMENT,
  `prospect_id` int DEFAULT NULL,
  `agent_id` int NOT NULL,
  `to_email` varchar(255) DEFAULT NULL,
  `sequence_step_id` int DEFAULT NULL,
  `subject` varchar(500) DEFAULT NULL,
  `body` text,
  `sent_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `opened_at` timestamp NULL DEFAULT NULL,
  `clicked_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `prospect_id` (`prospect_id`),
  KEY `sequence_step_id` (`sequence_step_id`),
  KEY `idx_agent_sent` (`agent_id`,`sent_at`),
  CONSTRAINT `sent_emails_ibfk_1` FOREIGN KEY (`prospect_id`) REFERENCES `prospects` (`id`) ON DELETE CASCADE,
  CONSTRAINT `sent_emails_ibfk_2` FOREIGN KEY (`agent_id`) REFERENCES `agents` (`id`) ON DELETE CASCADE,
  CONSTRAINT `sent_emails_ibfk_3` FOREIGN KEY (`sequence_step_id`) REFERENCES `sequence_steps` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=212 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

