  `active` tinyint(1) DEFAULT '1',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_seq_agent` (`sequence_id`,`agent_id`),
  KEY `agent_id` (`agent_id`),
  CONSTRAINT `sequence_assignments_ibfk_1` FOREIGN KEY (`sequence_id`) REFERENCES `sequences` (`id`) ON DELETE CASCADE,
  CONSTRAINT `sequence_assignments_ibfk_2` FOREIGN KEY (`agent_id`) REFERENCES `agents` (`id`) ON DELETE CASCADE
