INSERT INTO `sequences` VALUES (1,'Megan - Friendly Discovery','Warm, conversational cold outreach for IT leaders. Leads with curiosity about their current telecom setup.','active','2026-04-07 14:37:00','2026-04-07 14:37:00'),(2,'Lauren - Executive Consultant','Polished, peer-level outreach for senior buyers. Consultative approach focused on business outcomes.','active','2026-04-07 14:37:00','2026-04-07 14:37:00'),(3,'Kate - Direct Value Prop','Sharp, efficient outreach respecting buyer time. Data-driven with compelling stats and quick credibility.','active','2026-04-07 14:37:00','2026-04-07 14:37:00'),(4,'Scott - Enterprise Narrative','Enterprise-focused relationship building. Longer-form narrative about telecom transformation.','active','2026-04-07 14:37:00','2026-04-07 14:37:00');
